function [c, ct] = eci2ecef_gmst(gmst, xp, yp)
%ECI2ECEF_GMST  frames.eci2ecefGMST: C = W R3(gmst), with W = [1 0 xp; 0 1 -yp; -xp yp 1] only when xp or yp is not 0; and C'.
%   gmst: real[1] (passed a plain number)
%   xp: real[1] (passed a plain number)
%   yp: real[1] (passed a plain number)
%   returns c: real[1][3][3] (passed a plain number)
%   returns ct: real[1][3][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    c = zeros(3, 3);
    ct = zeros(3, 3);
    rz = asils.models.earthframes.rot3(gmst);
    c = rz;
    if ((xp ~= 0) || (yp ~= 0))
        w = [([1; 0; xp]).'; ([0; 1; (-(yp))]).'; ([(-(xp)); yp; 1]).'];
        c = asils.pc.mm(w, rz);
    end
    ct = (c).';
end
